from wd_common import *
import math
i=8
Z=lambda q,a:[('z',q),('b',a)]
def mala(r=60,c='#8a5a2a'):
    o=''.join(f'<circle cx="{r*math.cos(k/108*6.283):.1f}" cy="{r*math.sin(k/108*6.283):.1f}" r="2.6" fill="{c}"/>' for k in range(108))
    return o+f'<circle cx="0" cy="{r+8}" r="6" fill="#c0392b"/><path d="M0 {r+14} v16" stroke="#c0392b" stroke-width="3"/>'
def wheel(n,r,lab=''):
    return f'<circle r="{r}" fill="#fff8e7" stroke="#7a3b1f" stroke-width="2"/>'+''.join(f'<path d="M0 0 L{r*math.cos(k/n*6.283):.1f} {r*math.sin(k/n*6.283):.1f}" stroke="#d9c2a0"/>' for k in range(n))+T(0,4,lab,10)
fw=foreword(i,['A prayer string has 108 beads. A god has 108 names. Kṛṣṇa’s holiest temples number 108, as do the classical Upaniṣads, the dance-units of Bharata and the sun-salutations done on special days. Why this number? There is no single answer in the texts, but there are many old patterns that meet at 108.',
 'This part explains the mālā and how japa is counted, the 108 names, the places and texts that come in 108, the patterns in the sky and in arithmetic, and what teachers make of the number.',
 'Previous: '+L('/why-do-we/tulasi/','tulasī')+'. Next: '+L('/why-do-we/upavasa/','fasting')+'. Names in practice: '+L('/vishnu/vishnu-sahasranama/','Viṣṇu Sahasranāma')+'.'],Z('Is 108 a magic number?','A sacred one. Many good reasons point to it, none forces it.'))
gl=glance([('The mālā','108 beads plus the guru bead (meru)'),('Japa','Counting a name or mantra 108 times'),('Names','Aṣṭottaraśata-nāmāvalī: 108 names of a deity'),('Places','108 Divya Deśas of Viṣṇu (Śrīvaiṣṇava)'),('Texts','108 Upaniṣads in the Muktikā list'),('Dance','108 karaṇas in the Nāṭyaśāstra'),('Sky','27 nakṣatras × 4 quarters = 108'),('Zodiac','12 signs × 9 planets = 108'),('Arithmetic','1 × 2² × 3³ = 108'),('Meaning','Completeness; a full round of prayer')],
 S('A prayer string of 108 beads with a red guru bead',g(280,120,1.4,mala()),'#fff3cf',230),Z('Why not 100?','A hundred is round. 108 is round and a little more: a full circle with room to spare, some say.'),'A full round <b>of prayer</b>.')
mala_=reading('mala','THE MĀLĀ','108 beads and the guru bead',S('A hand holding a mala, the thumb moving beads, the guru bead at the end',g(280,120,1.6,mala())+'<path d="M330 200 q20 -20 10 -50" stroke="#e8c3a0" stroke-width="10" fill="none"/>','#fff3cf',230),
 ['<b>108 beads.</b> A full japa mālā has 108 beads; shorter ones have 54 or 27, fractions of 108.','<b>The meru.</b> An extra bead, the meru or guru bead, marks the start and end.','<b>Not crossed.</b> By common teaching, the meru is not crossed: at the end of a round, one turns the mālā and goes back. (Practices vary.)','<b>Materials.</b> Rudrākṣa for Śiva, tulasī for Viṣṇu, sphaṭika (crystal), lotus seeds, sandalwood.','<b>Personal.</b> A mālā received from a teacher is kept carefully and not shown off.'],Z('What happens if I cross the meru?','Nothing explodes. The teaching is: the guru is not stepped over.'),'Round to the guru, <b>and back</b>.')
japa=reading('japa','COUNTING JAPA','How the beads are moved',S('Close-up of a right hand: mala over the middle finger, thumb pulling the beads, index finger held away',g(280,200,3,'<path d="M-30 0 v-30 q0 -10 10 -10 h30 q10 0 10 10 v30z" fill="#e8c3a0"/><path d="M-26 -40 v-34 M-10 -40 v-44 M6 -40 v-40" stroke="#e8c3a0" stroke-width="10" stroke-linecap="round"/><path d="M22 -40 l14 -20" stroke="#d8b090" stroke-width="10" stroke-linecap="round"/>'+''.join(f'<circle cx="{-10}" cy="{-60+k*6}" r="3" fill="#8a5a2a"/>' for k in range(5))),'#fff3cf',230),
 ['<b>Right hand.</b> The mālā is commonly held in the right hand, hanging over the middle or ring finger.','<b>Thumb.</b> The thumb draws each bead toward oneself with each repetition.','<b>Index finger.</b> By common teaching the index finger does not touch the mālā; it stands for the ego. (Teaching.)','<b>Covered.</b> Many keep the hand in a cloth bag (gomukhī) while counting.','<b>Count.</b> One round is 108; vows may be many rounds a day.'],Z('Why keep the index finger away?','It points and accuses, the teachers say. Let it rest.'),'Thumb moves, <b>mind stays</b>.')
names=reading('names','108 NAMES','The aṣṭottaraśata',S('A scroll listing names with a lamp beside it',g(260,200,1.8,'<rect x="-60" y="-120" width="120" height="120" fill="#fff8e7" stroke="#7a3b1f" stroke-width="2"/>'+''.join(f'<path d="M-46 {-104+k*12} h92" stroke="#c9a66a" stroke-width="3"/>' for k in range(9)))+g(420,215,1.2,lamp()),'#fff3cf',215),
 ['<b>Aṣṭottaraśata.</b> “Hundred and eight”: lists of 108 names exist for most deities (aṣṭottaraśata-nāmāvalī).','<b>In pūjā.</b> Each name is spoken with “namaḥ” while a flower or leaf is offered: an archana of 108.','<b>Longer lists.</b> The thousand names (sahasranāma) are the larger form, e.g. '+L('/srividya/lalita-sahasranama/','Lalitā Sahasranāma')+'.','<b>Every god.</b> Gaṇeśa, Śiva, Viṣṇu, Lakṣmī, Durgā, Hanumān, Sūrya and others have 108-name lists.','<b>Short and complete.</b> A 108-name archana is long enough to be complete, short enough for daily use.'],Z('Are the 108 names fixed?','Each list is fixed in its tradition. Different traditions have different lists.'),'A name <b>for every bead</b>.')
places=cards('places','108 PLACES AND TEXTS','Where else the number appears',fig_row('A temple, a scroll, a dancer and a sun',[(tulu_temple(),.8),('<rect x="-20" y="-30" width="40" height="30" fill="#fff8e7" stroke="#7a3b1f"/>',1.2),(person('#c0392b'),1),('<circle r="18" fill="#f0c030"/>',1.2)],['Divya Deśas','Upaniṣads','karaṇas','namaskāras'],gy=150),
 [('🛕','108 Divya Deśas','The 108 holy shrines of Viṣṇu sung by the Āḻvārs, honoured by Śrīvaiṣṇavas.'),('📜','108 Upaniṣads','The Muktikā Upaniṣad lists 108 Upaniṣads.'),('💃','108 karaṇas','The Nāṭyaśāstra describes 108 karaṇas, the units of dance, carved on temple walls at Cidambaram.'),('☀️','108 Sūrya namaskāras','Done on special days such as Ratha Saptamī.'),('🌺','108 Śakti pīṭhas','Some lists count 108 seats of the Goddess; others 51 or 18 (see '+L('/temples-of-india/18-shakti-peethas/','18 Śakti Pīṭhas')+').'),('🔁','Rounds','108 pradakṣiṇās in some vows.')],None,'108 <b>keeps turning up</b>.',intro='Some of these lists are traditional counts; scholars sometimes find more or fewer items in them.')
sky=reading('sky','IN THE SKY','Nakṣatras, signs and planets',S('A ring of 27 star-mansions each divided into four, and a ring of 12 signs',g(160,130,1,wheel(27,90,'27 × 4'))+g(420,130,1,wheel(12,90,'12 × 9')),'#20243a',230),
 ['<b>27 × 4.</b> The Indian sky is divided into 27 lunar mansions (nakṣatras), each in four quarters (pādas): 108 quarters in all.','<b>12 × 9.</b> The 12 signs (rāśis) and the 9 planets (grahas) of Indian astrology give 108 combinations.','<b>The same circle.</b> Both patterns divide the same circle of the sky; each pāda is one 108th of it.','<b>Japa and time.</b> A round of the mālā is thus likened to a round of the heavens. (Interpretation.)','<b>See.</b> '+L('/festivals/panchanga/','Pañcāṅga')+' for the nakṣatras and the calendar.'],Z('So the mālā is a little sky?','In your hand. That is one of the nicest readings.'),'A round <b>of the heavens</b>.')
num=reading('numbers','IN NUMBERS','Arithmetic and the sun and moon',S('The numbers 1, 2², 3³ multiplying to 108; sun and moon with dotted measures',T(160,100,'1 × 2² × 3³',22)+T(160,140,'= 108',22)+g(400,120,1,'<circle r="30" fill="#f0c030"/>')+'<path d="M400 160 h100" stroke="#e0a800" stroke-dasharray="4 4"/>'+g(510,160,.5,moon()),'#fff3cf',215),
 ['<b>Powers.</b> 108 = 1¹ × 2² × 3³: the first three numbers raised to themselves. (Popular observation.)','<b>Digits.</b> 1 + 0 + 8 = 9, a number linked with completeness and the nine planets.','<b>Sun and moon.</b> The sun is roughly 108 of its own diameters from the earth, and the moon about 108 of its diameters away: an approximate coincidence often cited. (Approximate.)','<b>Not proof.</b> These are patterns noticed in the number, not the reason given in scripture.','<b>Counting.</b> 108 divides neatly by 2, 3, 4, 6, 9, 12, 18, 27, 36 and 54: useful for counting rounds and shares.'],Z('Did the ancients know the sun distance?','We do not know. It makes a good story; keep it as a pattern, not a proof.'),'Patterns, <b>not proof</b>.')
other=reading('beyond','BEYOND HINDUISM','Buddhist and Jain 108',S('A Buddhist bell, a Jain symbol and a Hindu mala side by side',g(140,200,1.4,'<path d="M-20 0 q0 -40 20 -40 q20 0 20 40z" fill="#c9a227"/>')+g(280,200,1.4,'<path d="M-24 -40 h48 M0 -64 v48" stroke="#c0392b" stroke-width="6"/>')+g(420,140,.7,mala()),'#fff3cf',215),
 ['<b>Buddhism.</b> Buddhist mālās also have 108 beads; in Japan, temple bells are rung 108 times at the New Year, for the 108 worldly passions.','<b>Jainism.</b> Jains use 108-bead strings for the Namokār prayer, counting the qualities of the holy beings.','<b>Shared.</b> The number travelled across Asia with Indian religions.','<b>Sikh and others.</b> Other Indian traditions also use prayer strings.','<b>Common ground.</b> 108 is a shared Indic sacred number.'],Z('So 108 is not only Hindu?','It is Indian, and Asia took it along.'),'A number <b>shared across faiths</b>.')
st=story('story','THE FIRST ROUND','Rohan counts 108',strip('Three panels: a boy gets a mala; he loses count; he finishes the round',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(50,180,.7,person('#f4f1ea'))+g(100,120,.4,mala()),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,180,.8,person('#1d4f8a',seat=True))+'<text x="100" y="80" font-size="30" fill="#c0392b">?</text>','#fff3cf'),
  ('<rect width="144" height="190" fill="#20243a"/>'+g(72,180,.8,person('#1d4f8a',seat=True))+g(72,110,.35,mala(c='#e0a800')),'#20243a')],['the gift','lost count','one round']),'A family evening (an illustrative story).',
 ['Grandfather gives Rohan a small rudrākṣa mālā. “One name for each bead. Then stop at the big red one.”','At forty-something Rohan loses count. “That is why there are beads,” says Grandfather. “You don’t count. They do.”','He finishes the round. 108 names, ten quiet minutes. He did not expect to like it.'])
mean=reading('meaning','WHAT IT MEANS','Completeness',S('A circle of beads becoming a circle of light',g(280,120,1.6,mala(c='#e0a800'))+'<circle cx="280" cy="120" r="110" fill="#e0a800" opacity=".12"/>','#20243a',230),
 ['<b>Complete.</b> In practice, 108 means “a full measure”: a complete round of prayer. (Common teaching.)','<b>No single source.</b> No one text explains 108 once and for all; its sacredness grew from many patterns together.','<b>Sky and self.</b> The mālā links personal prayer to the order of the heavens. (Interpretation.)','<b>Discipline.</b> A fixed count keeps the mind on the task: one more bead, one more name.','<b>Free to begin.</b> Start with one round. 108 is a beginning, not a limit.'],Z('So I should do 108 of everything?','Of prayer, if you can. Of laḍḍus, no.'),'One full round, <b>then another</b>.')
endp=end(i,['<b>Mālā.</b> 108 beads and the meru; counted with the thumb.','<b>Names.</b> Aṣṭottaraśata: 108 names in archana.','<b>Lists.</b> 108 Divya Deśas, Upaniṣads, karaṇas, sun-salutations.','<b>Patterns.</b> 27 × 4, 12 × 9, 1 × 2² × 3³.','<b>Meaning.</b> Completeness, a round of the heavens.'],'Part 10 is fasting.','A full round of prayer')
src=sources([('Number:','Wikipedia, “108 (number)” (mālā, aṣṭottaraśata, Divya Deśas, Muktikā Upaniṣad, Nāṭyaśāstra karaṇas, astronomy and Buddhist uses), “Japamala”, “Divya Desam”, “Karana (dance)”.')],'the sun–moon distance ratios are approximate; the Śakti pīṭha count differs by list; japa finger customs vary; meanings marked as interpretation are teachers’ readings.','No verse text is reproduced in this part.')
finish(i,'PART 9 OF 10 · MĀLĀ · NAMES · NAKṢATRAS',covart('A prayer string of 108 beads beside a ring of star-mansions',g(150,110,1,mala())+g(320,110,.8,wheel(27,90,'27 × 4'))),'A full round of prayer',
 'Why <b>108</b>: the mālā and its guru bead, counting <b>japa</b>, the 108 names, the 108 places and texts, the patterns in the sky and in numbers, and what the number means.',
 'Why 108? Explained and illustrated: japa mālā and meru, counting japa, aṣṭottaraśata nāmāvalī, 108 Divya Deśas, Upaniṣads and karaṇas, 27 nakṣatras × 4, 12 signs × 9 planets, arithmetic patterns, Buddhist and Jain 108.',
 [fw,gl,mala_,japa,names,places,sky,num,other,st,mean,endp,src])
